INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('400', '400', '400', NULL, NULL, NULL, '/lore/400/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('academie-de-larcane', 'Académie de l’arcane', 'academie-de-larcane', NULL, NULL, NULL, '/lore/academie-de-larcane/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('accessoires', 'Accessoires', 'accessoires', NULL, NULL, NULL, '/ressources/accessoires/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('acquis', 'Acquis', 'acquis', 'Les points d’une compétence qui ne se répartissent pas, mais se gagnent : par l’entraînement, les dons de la race, de l’ethnie et de la classe, l’armure portée, le métier et les accessoires, et la fiche de personnage du site les additionne. En règle générale, ils ne dépassent pas 5 par point de la caractéristique, le +1 de la magie innée compris.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('action', 'Action', 'action', 'L’action principale du tour, qui sert à attaquer, à lancer un sort, à utiliser un objet, à sprinter, à utiliser un don de type Action ou à faire une quatrième action rapide.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('action-bonus', 'Action bonus', 'action-bonus', 'Voir {{instant-cast|IC}}.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('action-rapide', 'Action rapide', 'action-rapide', 'Voir {{instant-cast|IC}}.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('alchimie', 'Alchimie', 'alchimie', NULL, NULL, NULL, '/ressources/alchimie/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('alchimie-primitive', 'Alchimie primitive', 'alchimie-primitive', NULL, NULL, NULL, '/ressources/alchimie-primitive/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('alignement', 'Alignement', 'alignement', 'La morale du personnage. Il évolue au fil de l’aventure, selon ses actes, ses décisions et ses paroles, et le MJ en tient les quatre scores : Loyal, Chaotique, Bon et Mauvais.', NULL, NULL, '/regles/alignement/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('alteration-detat', 'Altération d’état', 'alteration-detat', 'Un changement de la condition d’un personnage (poison, brûlure, peur, paralysie…) qui lui inflige des malus, souvent pendant plusieurs tours. Il en existe vingt, physiques ou mentales, et la plupart ont trois stades, de plus en plus forts.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('alterations-detats', 'Altérations d’états', 'alterations-detats', NULL, NULL, NULL, '/regles/alterations-d-etats/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('alterations-detats-et-mode-hyper', 'Altérations d''états et Mode Hyper', 'alterations-detats-et-mode-hyper', NULL, NULL, NULL, '/regles/alterations-d-etats-et-mode-hyper/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('ame', 'Âme', 'ame', 'La quatrième barre des utilisateurs de la Nécromancie (les âmes) et de la magie du Sang (le Sang). C’est une réserve de 10 points, qui se recharge de 1 par tour en combat et que demandent certains de leurs sorts.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('amelioration', 'Amélioration', 'amelioration', 'Le niveau d’une arme (de +1 à +10), d’une armure ou d’un bouclier (de +1 à +5). Le niveau choisi donne le bonus qu’il écrit, qui est déjà le total : +10 aux dégâts pour une arme +5, +10 AP et +10 AM pour une armure +5, +10 AP pour un bouclier +5. On paie toutes les étapes, une à une, sans en sauter aucune. Les crans de {{solidite|solidité}} : pour une arme, +1 du +5 au +9 et +2 au +10 ; pour une armure, +1 au +4 comme au +5 ; pour un bouclier, les crans s’additionnent, +1 du +1 au +4 et +2 au +5.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('anansi', 'Anansi', 'anansi', NULL, NULL, 'race:hybride', '/races/anansi/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('anansi-classe', 'Anansi (classe)', 'anansi-classe', NULL, NULL, 'classe:raciales', '/classes/anansi/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('anna', 'Anna', 'anna', NULL, NULL, NULL, '/lore/anna/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('arbaletrier', 'Arbalétrier', 'arbaletrier', NULL, NULL, 'classe:distance', '/classes/arbaletrier/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('archer', 'Archer', 'archer', NULL, NULL, 'classe:distance', '/classes/archer/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('archimage', 'Archimage', 'archimage', NULL, NULL, 'classe:speciales', '/classes/archimage/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('armes', 'Armes', 'armes', NULL, NULL, NULL, '/ressources/armes/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('armure-magique', 'Armure magique', 'armure-magique', 'Les points que l’armure retire aux dégâts des sorts. L’AM vient de la race, de l’ethnie, des classes magiques (4 chacune : voir {{classe-magique|Classe magique}}), des accessoires et de l’armure portée.', 'AM', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('armure-physique', 'Armure physique', 'armure-physique', 'Les points que l’armure retire aux dégâts des armes. Contre un coup d’estoc, de taille ou de frappe, l’armure portée les compte double ou moitié, selon qu’elle y résiste ou y est faible.', 'AP', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('armures', 'Armures', 'armures', NULL, NULL, NULL, '/ressources/armures/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('artisanat', 'Artisanat', 'artisanat', 'Fabriquer des objets, ce que seuls certains métiers permettent : il faut le bon métier. La compétence d’artisanat vaut 10 × la première caractéristique du métier + 10 × la seconde.', NULL, NULL, '/regles/artisanat/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('attaque-discrete', 'Attaque discrète', 'attaque-discrete', 'Frapper une cible qui ne vous voit pas venir, pour un dé de dégâts en plus. À ne pas confondre avec l’attaque sournoise, qui vient d’une classe.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('attaque-dopportunite', 'Attaque d’opportunité', 'attaque-dopportunite', 'Une attaque offerte hors de son tour, quand un adversaire rate son attaque contre vous sur un échec critique, quand il sort de votre zone d’influence (sauf si c’est vous qui l’en faites sortir), ou quand un don le permet. Une seule par tour et par joueur, sauf don qui en permet plus, et seulement une action simple.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('attaque-et-defense', 'Attaque et Défense', 'attaque-et-defense', NULL, NULL, NULL, '/regles/attaque-et-defense/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('attaque-gratuite', 'Attaque gratuite', 'attaque-gratuite', 'L’attaque que permet un adversaire qui quitte votre zone d’influence. Le Doc « Guide pour MJ » range aussi ce cas parmi les attaques d’opportunité (voir {{attaque-dopportunite|Attaque d’opportunité}} et {{zone-dinfluence|Zone d’influence}}).', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('attaquer-et-se-defendre', 'Attaquer et se défendre', 'attaquer-et-se-defendre', NULL, NULL, NULL, '/regles/attaquer-et-se-defendre/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('attributs', 'Attributs', 'attributs', 'Les valeurs de base du personnage (santé, {{chakra|chakra}}, {{barriere|barrière}}, {{corruption|corruption}}, vitesse, initiative, armure de base), et la quatrième barre pour la Nécromancie et la magie du Sang.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('aurora', 'Aurora', 'aurora', NULL, NULL, NULL, '/lore/aurora/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('balogne', 'Balogne', 'balogne', NULL, NULL, NULL, '/lore/balogne/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('barde', 'Barde', 'barde', NULL, NULL, 'classe:magiques', '/classes/barde/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('bardiche-du-bourreau-dechire', 'Bardiche du Bourreau déchiré', 'bardiche-du-bourreau-dechire', NULL, NULL, NULL, '/lore/bardiche-du-bourreau-dechire/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('barrage-argente', 'Barrage Argenté', 'barrage-argente', NULL, NULL, NULL, '/lore/barrage-argente/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('barriere', 'Barrière', 'barriere', 'Manifestation physique dérivée du {{chakra|Chakra}} d''un individu. Elle agit comme une seconde peau invisible protégeant le corps de blessures. Abrégée BA, elle vaut la moitié du {{chakra|chakra}} total, plus les bonus de la race et de la classe. Certains matériaux d’arme la contrent : le Mythril passe à travers, le Maverium la brise à son contact. Le Glossaire du Codex précise qu’elle prend les coups avant la santé, sauf contre-indication.', 'BA', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('baton-de-la-destruction', 'Bâton de la destruction', 'baton-de-la-destruction', NULL, NULL, NULL, '/lore/baton-de-la-destruction/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('baton-magique', 'Bâton magique', 'baton-magique', NULL, NULL, NULL, '/ressources/objets-a-la-ceinture/#batons-magiques');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('battlemap', 'Battlemap', 'battlemap', 'Voir {{carte-de-combat|Carte de combat}}.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('bauc', 'Bauc', 'bauc', NULL, NULL, NULL, '/lore/bauc/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('bestiaire', 'Bestiaire', 'bestiaire', NULL, NULL, NULL, '/bestiaire/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('biclassage', 'Biclassage', 'biclassage', 'Avoir deux classes. On peut commencer avec deux classes, chacune au niveau 1 et gagnant 1 niveau par niveau global ; avec une seule, qui commence au niveau 2 et en gagne 2 par niveau global jusqu’au niveau 20, qu’elle atteint au niveau global 10, une seconde classe est prise automatiquement au niveau global 11 et reçoit la suite. Au niveau global 20, tout personnage a donc deux classes au niveau 20.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('bienvenue-dans-maverick', 'Bienvenue dans Maverick', 'bienvenue-dans-maverick', NULL, NULL, 'partie:decouvrir', '/decouvrir/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('bimane', 'Bimane', 'bimane', NULL, NULL, 'classe:melee', '/classes/bimane/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('blessure-et-mort', 'Blessure et mort', 'blessure-et-mort', NULL, NULL, NULL, '/regles/blessures-et-etats/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('bois-du-printemps', 'Bois du printemps', 'bois-du-printemps', NULL, NULL, NULL, '/lore/bois-du-printemps/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('boss', 'Boss', 'boss', 'Un ennemi pensé pour affronter une équipe de quatre joueurs. Il a deux initiatives par tour, et plus de parades et d’esquives que les autres dans certaines postures.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('bouclier', 'Bouclier', 'bouclier', 'Une forme, sa classe de 1 à 5 (Bocle, Targe, Bouclier Rond, Écu, Pavois), et une matière, qui donne sa solidité. Ses AP et son AM ne comptent que sur une parade partielle faite avec lui, et son poids demande une Force minimum.', NULL, NULL, '/ressources/bouclier/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('brock', 'Brock', 'brock', NULL, NULL, NULL, '/lore/brock/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('cac', 'càc', 'cac', NULL, NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('camnau', 'Camnau', 'camnau', NULL, NULL, NULL, '/lore/camnau/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('campagne', 'Campagne', 'campagne', 'Une aventure en plusieurs séances, qui part d’un point A pour arriver à un point B ; les joueurs y font partie de l’écriture de l’histoire. Voir aussi {{one-shot|One shot}}.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('capacite-de-classe', 'capacité de classe', 'capacite-de-classe', NULL, NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('capse', 'Capse', 'capse', NULL, NULL, NULL, '/lore/capse/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('caracteristiques', 'Caractéristiques', 'caracteristiques', 'Les six valeurs de base du personnage, Force, Volonté, Intelligence, Perception, Social et Agilité, de 1 à 4 en règle générale (5 avec le +1 de la magie innée). Chacune compte dix fois dans le score de ses cinq compétences.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('carte-de-combat', 'Carte de combat', 'carte-de-combat', 'Une carte quadrillée vue de haut, où le MJ dessine les obstacles d’un combat et où l’on compte les distances en cases. Il peut s’en passer pour un combat rapide.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('ceinture', 'Ceinture', 'ceinture', 'Trois emplacements pour des objets à portée de main (fioles, carquois, bâtons magiques…), qui s’utilisent en une action rapide au lieu d’une action entière ; au plus 3 exemplaires du même objet dans chacun.', NULL, NULL, '/ressources/objets-a-la-ceinture/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('celsius', 'Celsius', 'celsius', NULL, NULL, NULL, '/lore/celsius/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('chakra', 'Chakra', 'chakra', 'Énergie consommée lors de l''utilisation de magie. Quand le chakra est épuisé, la santé est consommée à la hauteur de 3 points pour un de Chakra. Abrégé CK, il compte les points de magie du personnage, que dépensent ses sorts, et vient de la race, de la ou des classes et des magies.', 'CK', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('champicer', 'Champicer', 'champicer', NULL, NULL, NULL, '/lore/champicer/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('champieu', 'Champieu', 'champieu', NULL, NULL, NULL, '/lore/champieu/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('chapelle-des-os', 'Chapelle des Os', 'chapelle-des-os', NULL, NULL, NULL, '/lore/chapelle-des-os/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('chargement-mage-vert', 'Chargement (Mage Vert)', 'chargement-mage-vert', NULL, NULL, NULL, '/capacites/mage-vert-chargement/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('chronologie', 'Chronologie', 'chronologie', NULL, NULL, NULL, '/chronologie/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('classe', 'Classe', 'classe', 'La façon de se battre du personnage. Elle a son propre niveau, et lui donne de la santé, du {{chakra|chakra}} et de la {{barriere|barrière}}, des maîtrises d’armes et d’armures, un équipement de départ et des dons. Les classes se rangent en cinq catégories : physiques au corps à corps, physiques à distance, magiques, raciales et spéciales.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('classe-magique', 'Classe magique', 'classe-magique', 'Une classe de la catégorie des classes magiques ; l’Archimage, rangée dans les classes spéciales, en est une aussi. Elle donne 4 AM et compte comme une condition pour les emplacements de sorts. La seconde spécialité de chaque classe raciale, et celle du Flagelleur, donne elle aussi 4 AM.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('classe-raciale', 'Classe raciale', 'classe-raciale', 'La classe propre à une race hybride, qui porte son nom. Le Drassah’thac, hybride, n’en a pas.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('classes', 'Classes', 'classes', NULL, NULL, NULL, '/classes/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('clerc', 'Clerc', 'clerc', NULL, NULL, 'classe:magiques', '/classes/clerc/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('cloche-dor', 'Cloche d’or', 'cloche-dor', NULL, NULL, NULL, '/lore/cloche-dor/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('codex', 'codex', 'codex', NULL, NULL, NULL, '/lore/codex/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('collines-humides', 'Collines humides', 'collines-humides', NULL, NULL, NULL, '/lore/collines-humides/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('coma', 'Coma', 'coma', 'L’état d’un personnage dont la santé tombe à 0 ou moins. Inconscient, il fait des jets de Survie : un seul réussi le stabilise, trois ratés et il meurt.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('compagnie-du-fer-noir', 'Compagnie du Fer Noir', 'compagnie-du-fer-noir', NULL, NULL, NULL, '/lore/compagnie-du-fer-noir/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('competence', 'Compétence', 'competence', 'Un savoir-faire lié à une caractéristique (Diplomatie, Esquive, Magie…), avec son score. Il y en a trente, cinq par caractéristique.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('composants', 'Composants', 'composants', NULL, NULL, NULL, '/ressources/composants/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('confrerie-du-sang', 'Confrérie du Sang', 'confrerie-du-sang', NULL, NULL, NULL, '/lore/confrerie-du-sang/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('corruption', 'Corruption', 'corruption', 'Poison du chakra : chaque point de corruption prend la place d''un point de chakra, jusqu''au maximum du chakra ; le repos et la méditation ne la font pas baisser. Au maximum, le personnage a deux semaines pour en retirer un point, sinon il meurt et devient une abomination. Seuls ceux qui ont la Corruption en magie innée ou acquise ne risquent pas cette mort : pour eux, c''est la réserve où passe le chakra de leurs sorts. Le Potentiel Illimité, même s''il peut s''en servir, peut en mourir s''il en cumule trop. CR, dans les tableaux de sorts, désigne la corruption. « Si CR » : si le sort est lancé en utilisant la corruption. Dans les dégâts, soins ou barrière (D/S/B) ou les effets, « N CR » fait monter la corruption de la cible (le sort de soin Retrait en retire) ; dans le coût, c''est la corruption à dépenser.', 'CR', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('cout-secondaire', 'Coût secondaire', 'cout-secondaire', 'Ce qu’un sort coûte en plus de son {{chakra|chakra}} (des âmes pour la Nécromancie, du Sang pour la magie du Sang, ou autre chose encore, comme une part de la santé).', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('couturier', 'Couturier', 'couturier', NULL, NULL, NULL, '/metiers/#metier-couturier');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('creature-invoquee', 'Créature invoquée', 'creature-invoquee', 'Une créature appelée par un sort. Ce sont les morts de l’Animation de mort (Nécromancie), les golems de l’Appel aux Golems (Terre), les marionnettes de la Marionnette de l’ombre (Ombre). Elle n’a pas d’échelle de puissance : son rang est un NPM.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('creer-son-personnage', 'Créer son personnage', 'creer-son-personnage', NULL, NULL, 'partie:creer', '/regles/creer-son-personnage/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('croc-du-volcan', 'Croc du Volcan', 'croc-du-volcan', NULL, NULL, NULL, '/lore/croc-du-volcan/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('croix', 'Croix', 'croix', 'Une marque sous une caractéristique, laissée par une blessure grave, un traumatisme, une maladie, une mauvaise nuit ou certaines altérations d’état. Une croix retire 20 % à tous les jets de la caractéristique ; deux la rendent inutilisable, elle et ses compétences.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('cuirasse', 'Cuirassé', 'cuirasse', NULL, NULL, 'classe:melee', '/classes/cuirasse/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('defense-partielle', 'Défense partielle', 'defense-partielle', 'Une parade ou une esquive réussie, mais moins bonne que l’attaque. Les dégâts sont divisés par 2. Si c’est une parade partielle faite au bouclier, ses AP et son AM comptent : c’est le seul cas où ils comptent.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('degats', 'Dégâts', 'degats', 'Ce que perd la cible d’un coup réussi, en santé ou en {{barriere|barrière}}, une fois retirée son armure.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('des', 'Dés', 'des', 'La formule exacte est XDY+Z. X = Nombre de dés à lancer. Y = Nombre de faces du (des) dé(s). Il peut valoir 2 4 6 8 10 12 20 ou 100. Z = Bonus ou Malus à ajouter au résultat du dé. Le nombre écrit devant dit combien de dés lancer, et ce qui suit le « + » s’ajoute : « 2d6+2 », ce sont deux dés à six faces, additionnés, plus 2.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('dieu-choisi', 'Dieu choisi', 'dieu-choisi', 'Voir {{dieu-inne|Dieu inné}}.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('dieu-inne', 'Dieu inné', 'dieu-inne', 'Le dieu inné est la divinité de la magie innée du personnage (l’Espace/Temps en a deux) ; le dieu choisi, facultatif, est celui qu’il décide de prier (le Glossaire du Codex le nomme dieu acquis).', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('dimitri', 'Dimitri', 'dimitri', NULL, NULL, NULL, '/lore/dimitri/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('distance', 'distance', 'distance', NULL, NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('dombourg', 'Dombourg', 'dombourg', NULL, NULL, NULL, '/lore/dombourg/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('don', 'Don', 'don', 'Une capacité particulière, donnée par la race, par la classe ou par les événements de l’aventure. Un don est passif (toujours effectif), actif (à déclarer pour que son effet fonctionne), d’action (il prend l’action du tour) ou de réaction (il se joue en dehors de son tour).', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('don-de-base', 'Don de base', 'don-de-base', 'Le don que donne la race, Méditation (pour récupérer du {{chakra|chakra}}) ou Repos (pour récupérer de la santé et du {{chakra|chakra}}) ; une action, trois fois par jour.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('donjon-pas-bon', 'Donjon Pas bon', 'donjon-pas-bon', NULL, NULL, NULL, '/regles/donjon-pas-bon/');
