INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('double-coup-mage-vert', 'Double coup (Mage Vert)', 'double-coup-mage-vert', NULL, NULL, NULL, '/capacites/mage-vert-double-coup/');
