INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('echec-critique', 'Échec critique', 'echec-critique', 'Un résultat de 96 à 100 au D100. L’action rate complètement, et cela coûte quelque chose : un sort au double de son coût, une défense où l’armure ne compte plus…', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('echelle-de-puissance', 'Échelle de puissance', 'echelle-de-puissance', 'La classification indicative de la puissance d’un monstre, que donne sa carte du bestiaire. Les créatures invoquées n’en ont pas.', 'EP', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('eglise-du-sel', 'Église du Sel', 'eglise-du-sel', NULL, NULL, NULL, '/lore/eglise-du-sel/');
