INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('elfe-noir', 'Elfe noir', 'elfe-noir', NULL, NULL, 'race:pure', '/races/elfe-noir/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('embuscade', 'Embuscade', 'embuscade', 'Consommer l’action de son tour pour attendre un ennemi, et lui porter une attaque d’opportunité dès qu’il entre dans la zone voulue. La posture de vigilance la déjoue.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('empire-argente', 'Empire Argenté', 'empire-argente', NULL, NULL, NULL, '/lore/empire-argente/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('empire-humain', 'Empire Humain', 'empire-humain', NULL, NULL, NULL, '/lore/empire-humain/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('emplacement-de-sort', 'Emplacement de sort', 'emplacement-de-sort', 'La place d’un sort sur la fiche. Chaque condition remplie (une magie innée, une magie acquise, une classe magique, une seconde classe magique) en donne autant que la puissance magique.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('entrainement', 'Entraînement', 'entrainement', 'Un jet de D100 qui fait gagner des points d’acquis dans une compétence, auprès d’un entraîneur ou d’un PNJ important. Il ne fait progresser que 15 compétences au plus, et chacune de 10 % au plus.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('eoline', 'Éoline', 'eoline', NULL, NULL, NULL, '/lore/eoline/');
