INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('esquive', 'Esquive', 'esquive', 'Éviter un coup, avec la compétence Esquive (Agilité). Voir aussi {{parade|Parade}} et {{defense-partielle|Défense partielle}}.', NULL, NULL, NULL);
