INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('initiative', 'Initiative', 'initiative', 'Ce qui fixe l’ordre de jeu en combat. À chaque tour, chacun lance 1D20 et ajoute un bonus qui dépend de son Agilité ; on joue du plus haut résultat au plus bas.', 'INI', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('instant-cast', 'Instant Cast', 'instant-cast', 'Une action qui ne prend pas l’action du tour. Trois au plus par tour, jamais deux fois la même, toujours avant l’action ; un sort IC ne consomme pas le tour, sauf sur un échec critique.', 'IC', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('intervention', 'Intervention', 'intervention', 'En posture défensive, parer ou esquiver un coup à la place d’un allié adjacent.', NULL, NULL, NULL);
