INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('magie-acquise', 'Magie acquise', 'magie-acquise', 'Une seconde magie, facultative. Toutes les magies ne se mélangent pas, et avec deux magies, les sorts de niveau 5 restent fermés.', NULL, NULL, NULL);
