INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('magie-innee', 'Magie innée', 'magie-innee', 'La magie de naissance, héritée de l’un des parents, sauf si un dieu intervient ; tout le monde en a une. Elle donne +1 dans une caractéristique et relie le personnage à son dieu inné.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('magies', 'Magies', 'magies', NULL, NULL, NULL, '/magies/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('magique', 'magique', 'magique', NULL, NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('maitre-du-jeu', 'Maître du jeu', 'maitre-du-jeu', 'Celui qui raconte l’histoire, joue les PNJ et les monstres, et juge de ce qui est possible, improbable ou impossible.', 'MJ', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('maitrise-darme', 'Maîtrise d’arme', 'maitrise-darme', 'Le savoir-faire avec une catégorie d’arme. Sans maîtrise, l’arme lance 1 dé de dégâts ; chaque point de maîtrise en ajoute un, jusqu’à 4 points au plus par catégorie, donc 5 dés. Les points de toutes les sources s’additionnent, jusqu’à ce plafond ; au-delà, la fiche le signale, et les points en trop ne donnent pas de dé.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('majin', 'Majin', 'majin', NULL, NULL, 'race:pure', '/races/majin/');
