INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('meteo', 'Météo', 'meteo', NULL, NULL, NULL, '/regles/meteo/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('metier', 'Métier', 'metier', 'Un savoir-faire choisi à la création ou plus tard dans l’aventure. Il donne des bonus d’acquis ou d’attribut, des objets de départ et, pour certains, l’artisanat.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('metiers', 'Métiers', 'metiers', NULL, NULL, NULL, '/metiers/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('mineur', 'Mineur', 'mineur', NULL, NULL, NULL, '/metiers/#metier-mineur');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('minotaure', 'Minotaure', 'minotaure', NULL, NULL, 'race:hybride', '/races/minotaure/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('minotaure-classe', 'Minotaure (classe)', 'minotaure-classe', NULL, NULL, 'classe:raciales', '/classes/minotaure/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('mirada', 'Mirada', 'mirada', NULL, NULL, NULL, '/lore/mirada/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('mode-hyper', 'Mode Hyper', 'mode-hyper', 'L’état de surpuissance qui s’ouvre au niveau 2 : pour quelques tours, une fois par semaine, la magie du personnage ne fait plus qu’un avec lui. Le Mode Hyper 100 %, plus puissant encore, s’ouvre au niveau 10.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('mode-super', 'Mode Super', 'mode-super', 'Un équivalent moins puissant du Mode Hyper : une symbiose avec un objet légendaire ou enchanté.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('moine', 'Moine', 'moine', NULL, NULL, 'classe:melee', '/classes/moine/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('mont-cendre', 'Mont cendré', 'mont-cendre', NULL, NULL, NULL, '/lore/mont-cendre/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('monts-couloirs', 'Monts Couloirs', 'monts-couloirs', NULL, NULL, NULL, '/lore/monts-couloirs/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('mora', 'Mora', 'mora', NULL, NULL, NULL, '/lore/mora/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('mordhau', 'Mordhau', 'mordhau', 'Avec certaines armes de corps à corps (notamment les épées), prendre l''arme par la lame et frapper avec le manche. Elle peut ainsi faire des dégâts de frappe alors qu''elle en est incapable, mais a 30 % de chance de perdre un cran de solidité (exemple : plus de 70 au jet d''attaque).', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('morfot', 'Morfot', 'morfot', NULL, NULL, NULL, '/lore/morfot/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('mort-vivant', 'Mort-vivant', 'mort-vivant', NULL, NULL, 'race:pure', '/races/mort-vivant/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('mrode', 'Mrode', 'mrode', NULL, NULL, NULL, '/lore/mrode/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('nain', 'Nain', 'nain', NULL, NULL, 'race:pure', '/races/nain/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('namazu', 'Namazu', 'namazu', NULL, NULL, 'race:hybride', '/races/namazu/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('namazu-classe', 'Namazu (classe)', 'namazu-classe', NULL, NULL, 'classe:raciales', '/classes/namazu/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('naturel', 'Naturel', 'naturel', 'Les points de compétence que l’on répartit soi-même, à la création (100 points, 20 au plus dans une compétence) puis à chaque niveau.', 'Nat.', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('negatif-maximal', 'Négatif maximal', 'negatif-maximal', 'L’opposé de la santé maximum (−30 pour 30 de santé). Un personnage dans le coma qui y descend n’a droit qu’à un seul jet de survie, et à deux fois ce négatif, il meurt sur le coup.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('niveau-de-classe', 'Niveau de classe', 'niveau-de-classe', 'Le niveau propre à chaque classe, qui suit le niveau global. La classe donne ses dons à ses niveaux 1, 5, 10, 15 et 20, et sa spécialité à son niveau 10.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('niveau-de-maitrise', 'Niveau de maîtrise', 'niveau-de-maitrise', 'Ce qui renforce un sort, de 0 à 3 NM ; ce que chacun lui apporte est écrit sur le sort. Il se gagne par niveau, par la lecture d’un livre de sort ou en cadeau du MJ.', 'NM', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('niveau-de-puissance-magique', 'Niveau de puissance magique', 'niveau-de-puissance-magique', 'Le niveau d’un sort, de 1 à 5. Un sort n’est accessible que si la puissance magique du personnage atteint son NPM ; la page de chaque magie range ses sorts par NPM.', 'NPM', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('niveau-global', 'Niveau global', 'niveau-global', 'Le niveau du personnage, de 1 à 20, que fixe son total d’expérience. Il règle le niveau de ses classes et sa puissance magique.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('notix', 'Notix', 'notix', NULL, NULL, NULL, '/lore/notix/');
