INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('one-shot', 'One shot', 'one-shot', 'Une histoire jouée en une seule séance, avec une fin fermée, qui ne laisse pas de suite. Voir aussi {{campagne|Campagne}}.', NULL, NULL, NULL);
