INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('origine-du-monde', 'Origine du monde', 'origine-du-monde', NULL, NULL, NULL, '/lore/origine-du-monde/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('orios', 'Orios', 'orios', NULL, NULL, 'race:hybride', '/races/orios/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('orios-classe', 'Orios (classe)', 'orios-classe', NULL, NULL, 'classe:raciales', '/classes/orios/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('parade', 'Parade', 'parade', 'Bloquer un coup avec son arme ou son bouclier, avec la compétence Parade (Force). Voir aussi {{esquive|Esquive}} et {{defense-partielle|Défense partielle}}.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('parleur', 'Parleur', 'parleur', NULL, NULL, 'classe:speciales', '/classes/parleur/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('personnage-joueur', 'Personnage joueur', 'personnage-joueur', 'Un personnage joueur, celui qu’incarne un joueur ; un personnage non joueur, que joue le MJ, comme tous ceux que croisent les personnages.', 'PJ', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('personnage-non-joueur', 'Personnage non joueur', 'personnage-non-joueur', 'Voir {{personnage-joueur|Personnage joueur}}.', 'PNJ', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('piece-elementaire', 'Pièce élémentaire', 'piece-elementaire', 'Une pièce qui, posée sur une arme, une armure ou un vêtement, le transforme pour toujours en un équipement chargé de sa magie ; les bonus d’origine sont perdus.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('pieces-elementaires', 'Pièces élémentaires', 'pieces-elementaires', NULL, NULL, NULL, '/ressources/armes/#pieces-elementaires');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('plaine-brillante', 'Plaine brillante', 'plaine-brillante', NULL, NULL, NULL, '/lore/plaine-brillante/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('plaines-seches', 'Plaines sèches', 'plaines-seches', NULL, NULL, NULL, '/lore/plaines-seches/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('plateau-tonnerre', 'Plateau Tonnerre', 'plateau-tonnerre', NULL, NULL, NULL, '/lore/plateau-tonnerre/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('points-dexperience', 'Points d’expérience', 'points-dexperience', 'Les points d’expérience. Leur total fixe le niveau global.', 'XP', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('portee', 'Portée', 'portee', 'La distance qu’un sort ou une action peut atteindre. Celle d’une arme est le nombre de cases que parcourt son projectile, 1 pour une arme qui n’en écrit pas ; chaque diagonale y compte pour 2 cases.', 'PO', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('posture', 'Posture', 'posture', 'L’attitude de combat que l’on déclare au début de son tour. Il en existe six : Offensif, Défensif, Neutre, Focus, Vigilance et Symbiose.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('potentiel-illimite', 'Potentiel illimité', 'potentiel-illimite', NULL, NULL, 'magie:potentiel-illimite', '/magies/potentiel-illimite/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('pp', 'Pierre précieuse', 'pierre-precieuse', 'Monnaies : le Ricken de fer (RF), le Ricken d’or (RO) et la Pierre précieuse (PP). 1 PP = 1 000 RO.', 'PP', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('preparation-mage-rouge', 'Préparation (Mage Rouge)', 'preparation-mage-rouge', NULL, NULL, NULL, '/capacites/mage-rouge-preparation/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('pretire', 'Prétiré', 'pretire', 'Une fiche de personnage créée sur le site, visible de tous ; la liste des personnages les réunit.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('prise-en-tenaille', 'Prise en tenaille', 'prise-en-tenaille', 'Voir {{tenaille|Tenaille}}.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('pugiliste', 'Pugiliste', 'pugiliste', NULL, NULL, 'classe:melee', '/classes/pugiliste/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('puissance-magique', 'Puissance magique', 'puissance-magique', 'Le niveau de magie du personnage, de 1 à 5, qui augmente avec son niveau global. Elle dit jusqu’à quel NPM il peut lancer des sorts, et multiplie ses emplacements de sorts.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('race', 'race', 'race', NULL, NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('race-pure', 'Race pure', 'race-pure', 'Race pure, race hybride : les deux familles de races. Une race hybride a sa classe raciale, sauf le Drassah’thac.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('races', 'Races', 'races', NULL, NULL, NULL, '/races/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('rater-ses-sortileges', 'Rater ses sortilèges', 'rater-ses-sortileges', NULL, NULL, NULL, '/regles/rater-ses-sortileges/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('recharge-longue', 'Recharge longue', 'recharge-longue', 'Doit utiliser son action ou son mouvement pour recharger. Une propriété de certaines armes.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('recharge-tres-longue', 'Recharge très longue', 'recharge-tres-longue', 'Doit utiliser son action ET son mouvement pour recharger. Une propriété de certaines armes.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('regles-des-metiers', 'Règles des métiers', 'regles-des-metiers', NULL, NULL, NULL, '/metiers/regles-des-metiers/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('relations-entre-les-races', 'Relations entre les races', 'relations-entre-les-races', NULL, NULL, NULL, '/lore/relations-entre-les-races/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('remede', 'Remède', 'remede', 'Une potion contre une altération d’état. Le mineur la réduit d’un cran, le majeur de deux, le parfait la soigne entièrement.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('republique-forestier', 'République Forestier', 'republique-forestier', NULL, NULL, NULL, '/lore/republique-forestier/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('republique-noire', 'République Noire', 'republique-noire', NULL, NULL, NULL, '/lore/republique-noire/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('resistance', 'Résistance', 'resistance', 'Résistance, faiblesse (ou vulnérabilité) : ce qui fait prendre deux fois moins de dégâts d’une magie, ou deux fois plus. Elles se comptent en crans qui s’additionnent : deux résistances à la même magie font une grande résistance, deux faiblesses une grande vulnérabilité, une résistance et une faiblesse s’annulent. L’armure, elle, résiste ou est faible à des types de coups physiques.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('resistances-et-faiblesses', 'Résistances et faiblesses', 'resistances-et-faiblesses', NULL, NULL, NULL, '/regles/resistances-et-faiblesses/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('reussir-une-action', 'Réussir une action', 'reussir-une-action', NULL, NULL, NULL, '/regles/reussir-une-action/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('reussite-critique', 'Réussite critique', 'reussite-critique', 'Un résultat de 1 à 5 au D100, que des bonus élargissent (posture, score au-delà de 95 %, dons, sorts…), jamais au-delà de 1 à 15. L’action réussit de façon exceptionnelle : en attaque, les dégâts de base sont doublés.', 'RC', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('rf', 'Ricken de fer', 'ricken-de-fer', 'Monnaies : le Ricken de fer (RF), le Ricken d’or (RO) et la Pierre précieuse (PP). 1 RO = 100 RF.', 'RF', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('ro', 'Ricken d’or', 'ricken-dor', 'Monnaies : le Ricken de fer (RF), le Ricken d’or (RO) et la Pierre précieuse (PP). 1 RO = 100 RF, et 1 PP = 1 000 RO.', 'RO', NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('rokh', 'Rokh', 'rokh', NULL, NULL, 'race:hybride', '/races/rokh/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('rokh-classe', 'Rokh (classe)', 'rokh-classe', NULL, NULL, 'classe:raciales', '/classes/rokh/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('ruines-rouges', 'Ruines Rouges', 'ruines-rouges', NULL, NULL, NULL, '/lore/ruines-rouges/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('sang', 'Sang', 'sang', 'Voir {{ame|Âme}}.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('sante', 'Santé', 'sante', 'Les points de vie du personnage. À 0 ou moins, il tombe dans le coma.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('satyre', 'Satyre', 'satyre', NULL, NULL, 'race:hybride', '/races/satyre/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('satyre-classe', 'Satyre (classe)', 'satyre-classe', NULL, NULL, 'classe:raciales', '/classes/satyre/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('saugnane', 'Saugnane', 'saugnane', NULL, NULL, NULL, '/lore/saugnane/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('scenario-one-shot', 'Scénario one shot', 'scenario-one-shot', 'Voir {{one-shot|One shot}}.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('score', 'Score', 'score', 'Le pourcentage de réussite d’une compétence, qui vaut 10 × la caractéristique + les points naturels + les points acquis. Il faut faire son score ou moins au D100 pour réussir.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('selcalibur', 'Selcalibur', 'selcalibur', NULL, NULL, NULL, '/lore/selcalibur/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('sentrainer', 'S’entraîner', 'sentrainer', NULL, NULL, NULL, '/regles/s-entrainer-et-exercer-un-metier/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('seraphe', 'Séraphe', 'seraphe', NULL, NULL, NULL, '/lore/seraphe/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('seraphin', 'Séraphin', 'seraphin', NULL, NULL, NULL, '/lore/seraphin/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('signe-des-pirates', 'Signe des pirates', 'signe-des-pirates', NULL, NULL, NULL, '/lore/signe-des-pirates/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('situation-actuelle', 'Situation actuelle', 'situation-actuelle', NULL, NULL, NULL, '/lore/situation-actuelle/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('soir-matin', 'Soir-matin', 'soir-matin', NULL, NULL, NULL, '/lore/soir-matin/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('solidite', 'Solidité', 'solidite', 'État de l''équipement. Une Solidité à 0 rend l''objet inutilisable et exige une réparation à l''aide d''un kit de réparation, ou d''une compétence d''artisanat adaptée ainsi que du même matériau que l''objet. La solidité compte les mauvais coups (un coup critique, le coup d’un adversaire très fort…) qu’un équipement peut encaisser. Une armure en a une par partie (le casque, le torse, chaque bras, chaque jambe), sauf une armure à cran de solidité uni, qui n’en a qu’une.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('sort-fer', 'Sort fer', 'sort-fer', 'Type de sort d''amélioration qui s''applique sur une arme.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('sort-grenade', 'Sort grenade', 'sort-grenade', 'Type particulier de sort provoquant une explosion localisée.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('speciale', 'spéciale', 'speciale', NULL, NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('specialite', 'Spécialité', 'specialite', 'L’embranchement d’une classe, qui se choisit quand elle atteint le niveau 10 ; la page de la classe en donne les dons.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('sprint', 'Sprint', 'sprint', 'Doubler la distance parcourue pendant son tour. C’est l’action du tour : impossible d’attaquer après un sprint.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('super-gemme', 'Super Gemme', 'super-gemme', NULL, NULL, NULL, '/lore/super-gemme/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('temple-de-la-foudre', 'Temple de la Foudre', 'temple-de-la-foudre', NULL, NULL, NULL, '/lore/temple-de-la-foudre/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('temple-de-la-glace', 'Temple de la Glace', 'temple-de-la-glace', NULL, NULL, NULL, '/lore/temple-de-la-glace/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('temple-de-la-lumiere', 'Temple de la Lumière', 'temple-de-la-lumiere', NULL, NULL, NULL, '/lore/temple-de-la-lumiere/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('temple-de-la-terre', 'Temple de la Terre', 'temple-de-la-terre', NULL, NULL, NULL, '/lore/temple-de-la-terre/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('temple-de-leau', 'Temple de l’Eau', 'temple-de-leau', NULL, NULL, NULL, '/lore/temple-de-leau/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('temple-de-lespace-temps', 'Temple de l’Espace/Temps', 'temple-de-lespace-temps', NULL, NULL, NULL, '/lore/temple-de-lespace-temps/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('temple-de-lombre', 'Temple de l’Ombre', 'temple-de-lombre', NULL, NULL, NULL, '/lore/temple-de-lombre/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('temple-de-vent', 'Temple de Vent', 'temple-de-vent', NULL, NULL, NULL, '/lore/temple-de-vent/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('temple-du-feu', 'Temple du Feu', 'temple-du-feu', NULL, NULL, NULL, '/lore/temple-du-feu/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('temple-du-savoir', 'Temple du Savoir', 'temple-du-savoir', NULL, NULL, NULL, '/lore/temple-du-savoir/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('temple-noir', 'Temple noir', 'temple-noir', NULL, NULL, NULL, '/lore/temple-noir/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('temples-cultes-guildes', 'Temples/Cultes/Guildes', 'temples-cultes-guildes', NULL, NULL, NULL, '/lore/temples-cultes-guildes/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('tenaille', 'Tenaille', 'tenaille', 'Un ennemi encerclé au corps à corps par des alliés placés sur des cases opposées ; chaque allié de plus donne un avantage, jusqu’à quatre.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('terre-grise', 'Terre grise', 'terre-grise', NULL, NULL, NULL, '/lore/terre-grise/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('tisseurs-de-soi', 'Tisseurs de soi', 'tisseurs-de-soi', NULL, NULL, NULL, '/lore/tisseurs-de-soi/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('tofrom', 'Tofrom', 'tofrom', NULL, NULL, NULL, '/lore/tofrom/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('tounne', 'Tounne', 'tounne', NULL, NULL, NULL, '/lore/tounne/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('tour', 'Tour', 'tour', 'En combat, le temps se découpe en tours ; chacun agit à son tour, dans l’ordre de l’initiative, puis un nouveau tour commence.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('tour-de-charge', 'Tour de charge', 'tour-de-charge', 'Le tour passé à charger un sort de niveau 5 avant de le lancer. La posture Focus le supprime.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('tueur', 'Tueur', 'tueur', NULL, NULL, 'classe:melee', '/classes/tueur/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('umbro', 'Umbro', 'umbro', NULL, NULL, NULL, '/lore/umbro/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('un-maitre-du-jeu', 'Un maître du Jeu', 'un-maitre-du-jeu', NULL, NULL, NULL, '/mj/un-maitre-du-jeu/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('vampires-primordiaux', 'Vampires primordiaux', 'vampires-primordiaux', NULL, NULL, NULL, '/lore/vampires-primordiaux/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('ville-oeil', 'Ville-Oeil', 'ville-oeil', NULL, NULL, NULL, '/lore/ville-oeil/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('vitesse', 'Vitesse', 'vitesse', 'Le nombre de cases que le personnage parcourt en un tour. Il en a deux, sur terre et à la nage : celles de sa race, que l’équipement, les accessoires et les sorts peuvent changer.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('voleur', 'Voleur', 'voleur', NULL, NULL, 'classe:melee', '/classes/voleur/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('volt', 'Volt', 'volt', NULL, NULL, NULL, '/lore/volt/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('vulnerabilite', 'Vulnérabilité', 'vulnerabilite', 'Voir {{resistance|Résistance}}.', NULL, NULL, NULL);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('xendown', 'Xendown', 'xendown', NULL, NULL, NULL, '/lore/xendown/');
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url) VALUES ('zone-dinfluence', 'Zone d’influence', 'zone-dinfluence', 'Les cases devant un adversaire, derrière lui, à sa gauche et à sa droite. Y entrer puis la traverser lui permet une attaque d’opportunité ; la quitter, une attaque gratuite, que le Doc « Guide pour MJ » range aussi parmi les attaques d’opportunité.', NULL, NULL, NULL);
